   286	 *
   287	 * Converts a possibly ACE encoded domain name in UTF-8 format into a
   288	 * UTF-8 string (punycode decoding). The output buffer will be zero-terminated
   289	 * and must be deallocated by the caller.
   290	 *
   291	 * @output may be NULL to test lookup of @input without allocating memory.
   292	 *
   293	 * Returns:
   294	 *   %IDN2_OK: The conversion was successful.
   295	 *   %IDN2_TOO_BIG_DOMAIN: The domain is too long.
   296	 *   %IDN2_TOO_BIG_LABEL: A label is would have been too long.
   297	 *   %IDN2_ENCODING_ERROR: Character conversion failed.
   298	 *   %IDN2_MALLOC: Memory allocation failed.
   299	 *
   300	 * Since: 2.0.0
   301	 **/
   302	int
   303	idn2_to_unicode_8z8z (const char * input, char ** output, int flags)
   304	{
   305	  uint32_t *output_u32;
   306	  uint8_t *output_u8;
   307	  size_t length;
   308	  int rc;
   309	
   310	  rc = idn2_to_unicode_8z4z (input, &output_u32, flags);
   311	  if (rc != IDN2_OK || !input)
   312	    return rc;
   313	
   314	  output_u8 = u32_to_u8 (output_u32, u32_strlen(output_u32) + 1, NULL, &length);
   315	  free (output_u32);
   316	
   317	  if (!output_u8)
   318	    {
   319	      if (errno == ENOMEM)
   320	        return IDN2_MALLOC;
   321	      return IDN2_ENCODING_ERROR;
   322	    }
   323	
   324	  if (output)
   325	    *output = (char *) output_u8;
