   332	/**
   333	 * idn2_to_unicode_8zlz:
   334	 * @input: Input zero-terminated UTF-8 string.
   335	 * @output: Newly allocated output string in current locale's character set.
   336	 * @flags: Currently unused.
   337	 *
   338	 * Converts a possibly ACE encoded domain name in UTF-8 format into a
   339	 * string encoded in the current locale's character set (punycode
   340	 * decoding). The output buffer will be zero-terminated and must be
   341	 * deallocated by the caller.
   342	 *
   343	 * @output may be NULL to test lookup of @input without allocating memory.
   344	 *
   345	 * Returns:
   346	 *   %IDN2_OK: The conversion was successful.
   347	 *   %IDN2_TOO_BIG_DOMAIN: The domain is too long.
   348	 *   %IDN2_TOO_BIG_LABEL: A label is would have been too long.
   349	 *   %IDN2_ENCODING_ERROR: Character conversion failed.
   350	 *   %IDN2_MALLOC: Memory allocation failed.
   351	 *
   352	 * Since: 2.0.0
   353	 **/
   354	int
   355	idn2_to_unicode_8zlz (const char * input, char ** output, int flags)
   356	{
   357	  int rc;
   358	  uint8_t *output_u8, *output_l8;
   359	  const char *encoding;
   360	
   361	  rc = idn2_to_unicode_8z8z (input, (char **) &output_u8, flags);
   362	  if (rc != IDN2_OK || !input)
   363	    return rc;
   364	
   365	  encoding = locale_charset ();
   366	  output_l8 = (uint8_t*) u8_strconv_to_encoding (output_u8, encoding, iconveh_error);
   367	
   368	  if (!output_l8)
   369	    {
   370	      if (errno == ENOMEM)
   371	        rc = IDN2_MALLOC;
   372	      else
   373	        rc = IDN2_ENCODING_ERROR;
   374	
   375	      free(output_l8);
   376	    }
   377	  else
   378	    {
   379	      if (output)
   380	        *output = (char *) output_l8;
   381	      else
   382	        free (output_l8);
   383	
   384	      rc = IDN2_OK;
   385	    }
   386	
   387	  free (output_u8);
   388	
   389	  return rc;
   390	}
