   408	 *   %IDN2_TOO_BIG_LABEL: A label is would have been too long.
   409	 *   %IDN2_ENCODING_ERROR: Output character conversion failed.
   410	 *   %IDN2_ICONV_FAIL: Input character conversion failed.
   411	 *   %IDN2_MALLOC: Memory allocation failed.
   412	 *
   413	 * Since: 2.0.0
   414	 **/
   415	int
   416	idn2_to_unicode_lzlz (const char * input, char ** output, int flags)
   417	{
   418	  uint8_t *input_l8;
   419	  const char *encoding;
   420	  int rc;
   421	
   422	  if (!input)
   423	    {
   424	      if (output)
   425	        *output = NULL;
   426	      return IDN2_OK;
   427	    }
   428	
   429	  encoding = locale_charset ();
